def syms(S):
    ret={}
    for k in range(4):
        R={(r,c) for r,c in S}
        for _ in range(k): R={(c,4-r) for r,c in R}
        ret[f'rot{k*90}']=R
        ret[f'rot{k*90}_flip']= {(r,4-c) for r,c in R}
    return ret
